using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Web.Script.Serialization;
public static class PolicyTests {
 static int count;static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);count++;}static void Reject(Action action,string label){bool failed=false;try{action();}catch(Exception ex){if(!(ex is IOException||ex is CryptographicException||ex is ArgumentException||ex is FormatException))throw;failed=true;}Check(failed,label);}
 static string Sign(ServiceDocument policy,RSACryptoServiceProvider rsa){var json=new JavaScriptSerializer();byte[] bytes=Encoding.UTF8.GetBytes(json.Serialize(policy));return json.Serialize(new SignedServicePolicy{Payload=Convert.ToBase64String(bytes),Signature=Convert.ToBase64String(rsa.SignData(bytes,CryptoConfig.MapNameToOID("SHA256")))});}
 public static int Main(){try{using(var rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;string key=rsa.ToXmlString(false);var p=new ServiceDocument{Schema=1,State="active",Announcement="Maintenance announcement",RequiredVersion="3.3.0",PublishedUtc=DateTime.UtcNow.ToString("o"),Release=new ServiceRelease{Tag="v3.3.0",Url="https://github.com/w-rakeeb/dual-steam/releases/download/v3.3.0/Dual-Steam-Windows.zip",Sha256=new string('a',64),Size=123}};string signed=Sign(p,rsa);var accepted=ServicePolicy.Verify(signed,key);Check(ServicePolicy.Decision(accepted,new Version(3,3,0))=="allowed","signed active startup policy accepted");Check(ServicePolicy.Decision(accepted,new Version(3,2,0))=="update","older public version requires update at startup");Check(ServicePolicy.Decision(accepted,new Version(3,4,0))=="allowed","newer compatible version accepted");p.State="paused";Check(ServicePolicy.Decision(ServicePolicy.Verify(Sign(p,rsa),key),new Version(3,3,0))=="paused","pause announcement blocks new startup");Check(ServicePolicy.Decision(accepted,new Version(3,3,0))=="allowed","already authorized snapshot is unchanged by a later policy");p.State="shutdown";Check(ServicePolicy.Decision(ServicePolicy.Verify(Sign(p,rsa),key),new Version(3,3,0))=="shutdown","closed-service announcement blocks new startup");p.State="active";
 var envelope=new JavaScriptSerializer().Deserialize<SignedServicePolicy>(signed);envelope.Payload=Convert.ToBase64String(Encoding.UTF8.GetBytes("{\"Schema\":1}"));Reject(()=>ServicePolicy.Verify(new JavaScriptSerializer().Serialize(envelope),key),"tampered payload rejected");Reject(()=>ServicePolicy.Verify("{}",key),"unsigned policy rejected");using(var other=new RSACryptoServiceProvider(2048)){other.PersistKeyInCsp=false;Reject(()=>ServicePolicy.Verify(signed,other.ToXmlString(false)),"wrong publisher key rejected");}p.Release.Url="https://example.com/update.zip";Reject(()=>ServicePolicy.Verify(Sign(p,rsa),key),"foreign update download rejected");p.Release.Url="https://github.com/w-rakeeb/dual-steam/releases/download/v3.3.0/Dual-Steam-Windows.zip";p.Release.Sha256="";Reject(()=>ServicePolicy.Verify(Sign(p,rsa),key),"missing update checksum rejected");p.Release.Sha256=new string('a',64);p.RequiredVersion="3.4.0";Reject(()=>ServicePolicy.Verify(Sign(p,rsa),key),"mismatched required release rejected");p.RequiredVersion="3.3.0";p.State="unknown";Reject(()=>ServicePolicy.Verify(Sign(p,rsa),key),"unknown service state rejected");}
 string home=Path.Combine(Engine.Home,"Verification","No-Session-"+Guid.NewGuid().ToString("N"));Check(!RuntimeAuthorization.Valid(home),"missing manager authorization fails closed");Console.WriteLine(count+" policy checks passed.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
